class Pipeline:
    def __init__(self):
        self.middlewares = []

    def use(self, middleware_fn):
        self.middlewares.append(middleware_fn)
        return self

    def execute(self, request):
        def next_fn(index=0):
            if index == len(self.middlewares):
                return request
            middleware = self.middlewares[index]
            return middleware(request, lambda: next_fn(index + 1))
        return next_fn()
