import uuid
from collections import deque

class BankAccount:
    def __init__(self):
        self.events = deque(maxlen=100)  # Store last 100 events
        self.balance = 0
        self.event_count = 0

    def _apply_event(self, event):
        if event['type'] == 'deposit':
            self.balance += event['amount']
        elif event['type'] == 'withdraw':
            self.balance -= event['amount']

    def deposit(self, amount):
        if amount > 0:
            event = {'type': 'deposit', 'amount': amount}
            self.events.append(event)
            self._apply_event(event)
            self.event_count += 1
            if self.event_count % 10 == 0:
                self._create_snapshot()

    def withdraw(self, amount):
        if 0 < amount <= self.balance:
            event = {'type': 'withdraw', 'amount': amount}
            self.events.append(event)
            self._apply_event(event)
            self.event_count += 1
            if self.event_count % 10 == 0:
                self._create_snapshot()

    def get_balance(self):
        return self.balance

    def _create_snapshot(self):
        snapshot = {
            'balance': self.balance,
            'event_count': self.event_count
        }
        self._load_from_snapshot(snapshot)

    def _load_from_snapshot(self, snapshot):
        self.balance = snapshot['balance']
        self.event_count = snapshot['event_count']
        self.events.clear()

    def rebuild_state(self):
        self.balance = 0
        for event in self.events:
            self._apply_event(event)
