import redis
import time
from contextlib import AbstractContextManager

class DistributedLock(AbstractContextManager):
    def __init__(self, redis_client: redis.Redis, name: str, ttl: int = 30):
        self.redis = redis_client
        self.name = name
        self.ttl = ttl
        self.acquired = False

    def acquire(self, timeout: int = 10) -> bool:
        end_time = time.time() + timeout
        while time.time() < end_time:
            if self.redis.set(self.name, 1, nx=True, ex=self.ttl):
                self.acquired = True
                return True
            time.sleep(0.1)
        return False

    def release(self):
        if self.acquired:
            self.redis.delete(self.name)
            self.acquired = False

    def extend(self):
        if self.acquired:
            self.redis.expire(self.name, self.ttl)

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.release()
