from abc import ABC, abstractmethod
from typing import Any, Dict, Callable

class Command(ABC):
    pass

class Query(ABC):
    pass

class CommandHandler(ABC):
    @abstractmethod
    def handle(self, command: Command) -> None:
        pass

class QueryHandler(ABC):
    @abstractmethod
    def handle(self, query: Query) -> Any:
        pass

class Mediator:
    def __init__(self):
        self.command_handlers: Dict[type, CommandHandler] = {}
        self.query_handlers: Dict[type, QueryHandler] = {}

    def register_command_handler(self, command_type: type, handler: CommandHandler):
        self.command_handlers[command_type] = handler

    def register_query_handler(self, query_type: type, handler: QueryHandler):
        self.query_handlers[query_type] = handler

    def send(self, request: Command | Query) -> Any:
        if isinstance(request, Command):
            handler = self.command_handlers.get(type(request))
            if not handler:
                raise ValueError(f"No handler registered for command of type {type(request)}")
            handler.handle(request)
        elif isinstance(request, Query):
            handler = self.query_handlers.get(type(request))
            if not handler:
                raise ValueError(f"No handler registered for query of type {type(request)}")
            return handler.handle(request)
        else:
            raise ValueError("Invalid request type")

class ExampleCommand(Command):
    def __init__(self, value: int):
        self.value = value

class ExampleQuery(Query):
    def __init__(self, value: int):
        self.value = value

class ExampleCommandHandler(CommandHandler):
    def handle(self, command: ExampleCommand) -> None:
        print(f"Handling command with value: {command.value}")

class ExampleQueryHandler(QueryHandler):
    def handle(self, query: ExampleQuery) -> str:
        return f"Query result for value: {query.value}"

mediator = Mediator()
mediator.register_command_handler(ExampleCommand, ExampleCommandHandler())
mediator.register_query_handler(ExampleQuery, ExampleQueryHandler())

mediator.send(ExampleCommand(10))
result = mediator.send(ExampleQuery(20))
print(result)
