from collections import deque
from typing import Dict, List, Any, Callable, Optional

class Plugin:
    def __init__(self, name: str, version: str, dependencies: Optional[List[str]] = None):
        self.name = name
        self.version = version
        self.dependencies = dependencies if dependencies else []
        self.is_loaded = False

    def on_load(self):
        pass

    def on_unload(self):
        pass

    def on_event(self, event: str, data: Any):
        pass

class PluginManager:
    def __init__(self):
        self.plugins: Dict[str, Plugin] = {}
        self.loaded_plugins: List[Plugin] = []

    def register_plugin(self, plugin: Plugin):
        self.plugins[plugin.name] = plugin

    def load_plugins(self):
        load_queue = deque([plugin for plugin in self.plugins.values() if not plugin.dependencies])

        while load_queue:
            plugin = load_queue.popleft()
            if not plugin.is_loaded:
                for dep_name in plugin.dependencies:
                    dep = self.plugins.get(dep_name)
                    if dep and not dep.is_loaded:
                        load_queue.append(dep)

                plugin.on_load()
                plugin.is_loaded = True
                self.loaded_plugins.append(plugin)

        for plugin in self.plugins.values():
            if not plugin.is_loaded:
                raise RuntimeError(f"Plugin {plugin.name} could not be loaded due to unmet dependencies.")

    def unload_plugins(self):
        for plugin in reversed(self.loaded_plugins):
            plugin.on_unload()
            plugin.is_loaded = False
        self.loaded_plugins.clear()

    def trigger_event(self, event: str, data: Any):
        for plugin in self.loaded_plugins:
            plugin.on_event(event, data)
