"""
Event-sourced BankAccount implementation with snapshotting using Claude as the backbone.
Uses Claude to intelligently manage event sourcing, snapshots, and state reconstruction.
"""

import json
from datetime import datetime
from anthropic import Anthropic

client = Anthropic()


class EventSourcedBankAccount:
    """A bank account using event sourcing with Claude-powered event management and snapshotting."""

    def __init__(self, account_id: str, initial_balance: float = 0):
        """Initialize the bank account with event sourcing."""
        self.account_id = account_id
        self.events = []
        self.snapshots = []
        self.current_balance = initial_balance
        self.conversation_history = []

        if initial_balance > 0:
            self._add_event("account_created", {"initial_balance": initial_balance})

    def _add_event(self, event_type: str, data: dict) -> None:
        """Add an event to the event log."""
        event = {
            "type": event_type,
            "timestamp": datetime.now().isoformat(),
            "data": data,
            "event_number": len(self.events) + 1
        }
        self.events.append(event)

        if len(self.events) % 10 == 0:
            self._create_snapshot()

    def _create_snapshot(self) -> None:
        """Create a snapshot of the current state."""
        snapshot = {
            "balance": self.current_balance,
            "event_count": len(self.events),
            "timestamp": datetime.now().isoformat()
        }
        self.snapshots.append(snapshot)

        self.conversation_history.append({
            "role": "user",
            "content": f"Snapshot created at event #{len(self.events)}: Current balance is ${self.current_balance}"
        })

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=100,
            messages=self.conversation_history
        )

        assistant_message = response.content[0].text
        self.conversation_history.append({
            "role": "assistant",
            "content": assistant_message
        })

    def _rebuild_state(self) -> None:
        """Rebuild the current state from events and snapshots."""
        self.current_balance = 0

        start_from = 0
        if self.snapshots:
            latest_snapshot = self.snapshots[-1]
            self.current_balance = latest_snapshot["balance"]
            start_from = latest_snapshot["event_count"]

        for event in self.events[start_from:]:
            if event["type"] == "account_created":
                self.current_balance = event["data"]["initial_balance"]
            elif event["type"] == "deposit":
                self.current_balance += event["data"]["amount"]
            elif event["type"] == "withdrawal":
                self.current_balance -= event["data"]["amount"]

    def deposit(self, amount: float) -> dict:
        """Deposit money into the account."""
        if amount <= 0:
            return {"success": False, "error": "Deposit amount must be positive"}

        self._add_event("deposit", {"amount": amount})
        self._rebuild_state()

        self.conversation_history.append({
            "role": "user",
            "content": f"Deposit of ${amount} made to account {self.account_id}. New balance: ${self.current_balance}"
        })

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=150,
            messages=self.conversation_history
        )

        assistant_message = response.content[0].text
        self.conversation_history.append({
            "role": "assistant",
            "content": assistant_message
        })

        return {
            "success": True,
            "amount": amount,
            "new_balance": self.current_balance,
            "event_count": len(self.events),
            "claude_insight": assistant_message
        }

    def withdraw(self, amount: float) -> dict:
        """Withdraw money from the account."""
        if amount <= 0:
            return {"success": False, "error": "Withdrawal amount must be positive"}

        if amount > self.current_balance:
            return {"success": False, "error": f"Insufficient funds. Current balance: ${self.current_balance}"}

        self._add_event("withdrawal", {"amount": amount})
        self._rebuild_state()

        self.conversation_history.append({
            "role": "user",
            "content": f"Withdrawal of ${amount} from account {self.account_id}. New balance: ${self.current_balance}"
        })

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=150,
            messages=self.conversation_history
        )

        assistant_message = response.content[0].text
        self.conversation_history.append({
            "role": "assistant",
            "content": assistant_message
        })

        return {
            "success": True,
            "amount": amount,
            "new_balance": self.current_balance,
            "event_count": len(self.events),
            "claude_insight": assistant_message
        }

    def get_balance(self) -> dict:
        """Get the current account balance."""
        self.conversation_history.append({
            "role": "user",
            "content": f"Current balance query for account {self.account_id}: ${self.current_balance}"
        })

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=150,
            messages=self.conversation_history
        )

        assistant_message = response.content[0].text
        self.conversation_history.append({
            "role": "assistant",
            "content": assistant_message
        })

        return {
            "balance": self.current_balance,
            "account_id": self.account_id,
            "total_events": len(self.events),
            "total_snapshots": len(self.snapshots),
            "claude_summary": assistant_message
        }

    def get_event_history(self) -> list:
        """Get the complete event history."""
        return self.events.copy()

    def get_snapshot_history(self) -> list:
        """Get the complete snapshot history."""
        return self.snapshots.copy()

    def get_account_status(self) -> dict:
        """Get detailed account status with Claude analysis."""
        total_deposits = sum(e["data"]["amount"] for e in self.events if e["type"] == "deposit")
        total_withdrawals = sum(e["data"]["amount"] for e in self.events if e["type"] == "withdrawal")

        status_info = {
            "account_id": self.account_id,
            "current_balance": self.current_balance,
            "total_deposits": total_deposits,
            "total_withdrawals": total_withdrawals,
            "total_events": len(self.events),
            "total_snapshots": len(self.snapshots)
        }

        self.conversation_history.append({
            "role": "user",
            "content": f"Provide analysis of account status: {json.dumps(status_info)}"
        })

        response = client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=200,
            messages=self.conversation_history
        )

        assistant_message = response.content[0].text
        self.conversation_history.append({
            "role": "assistant",
            "content": assistant_message
        })

        status_info["claude_analysis"] = assistant_message
        return status_info


def main():
    """Demonstrate the event-sourced bank account with snapshotting."""
    print("=== Event-Sourced Bank Account with Snapshotting ===\n")

    account = EventSourcedBankAccount("ACC001", initial_balance=1000)
    print(f"Account created with initial balance: $1000\n")

    for i in range(12):
        if i % 3 == 0:
            result = account.deposit(100)
            print(f"Deposit ${result['amount']}: New balance = ${result['new_balance']}")
        else:
            result = account.withdraw(50)
            print(f"Withdraw ${result['amount']}: New balance = ${result['new_balance']}")

        if (i + 1) % 10 == 0:
            print(f"  ⚡ Snapshot created after event #{i + 1}\n")

    print("\n=== Final Account Status ===")
    status = account.get_account_status()
    print(json.dumps({k: v for k, v in status.items() if k != "claude_analysis"}, indent=2))
    print(f"\nClaude Analysis:\n{status['claude_analysis']}")

    print(f"\n=== Event History (first 5 events) ===")
    events = account.get_event_history()
    for event in events[:5]:
        print(f"Event #{event['event_number']}: {event['type']} - {event['data']}")

    print(f"\n=== Snapshots ===")
    snapshots = account.get_snapshot_history()
    for i, snapshot in enumerate(snapshots, 1):
        print(f"Snapshot {i}: Balance = ${snapshot['balance']} at event #{snapshot['event_count']}")


if __name__ == "__main__":
    main()
```

```python
"""
Plugin management system with lifecycle hooks and dependency management.
Uses Claude to analyze plugin dependencies and enforce load order.
"""

import json
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Set
from anthropic import Anthropic


@dataclass
class Plugin:
    """Represents a plugin with metadata and lifecycle hooks."""

    name: str
    version: str
    dependencies: List[str] = field(default_factory=list)
    on_load: Optional[Callable] = None
    on_unload: Optional[Callable] = None
    on_event: Optional[Callable[[str, Dict[str, Any]], None]] = None

    def __post_init__(self):
        """Validate plugin configuration."""
        if not self.name:
            raise ValueError("Plugin name cannot be empty")
        if not self.version:
            raise ValueError("Plugin version cannot be empty")
        if not isinstance(self.dependencies, list):
            raise ValueError("Dependencies must be a list")


class PluginManager:
    """Manages plugins with dependency resolution and lifecycle management."""

    def __init__(self):
        """Initialize the plugin manager with Claude AI assistance."""
        self.plugins: Dict[str, Plugin] = {}
        self.loaded_plugins: Set[str] = set()
        self.client = Anthropic()
        self.conversation_history: List[Dict[str, str]] = []
        self.system_prompt = """You are a plugin dependency analyzer. 
Your job is to:
1. Analyze plugin dependencies and detect circular dependencies
2. Determine the correct load order for plugins
3. Identify missing dependencies
4. Provide dependency analysis in JSON format

When asked to analyze plugins, respond with a JSON object containing:
{
    "valid": boolean,
    "load_order": [list of plugin names in order],
    "circular_dependencies": [list of circular dependency chains if any],
    "missing_dependencies": [list of unmet dependencies],
    "analysis": "text explanation"
}"""

    def register_plugin(self, plugin: Plugin) -> None:
        """Register a new plugin with the manager."""
        if plugin.name in self.plugins:
            raise ValueError(f"Plugin '{plugin.name}' is already registered")
        self.plugins[plugin.name] = plugin

    def _get_dependency_analysis(self, target_plugin: str) -> Dict[str, Any]:
        """Use Claude to analyze plugin dependencies."""
        # Prepare plugin data for analysis
        plugin_data = {
            name: {
                "version": p.version,
                "dependencies": p.dependencies
            }
            for name, p in self.plugins.items()
        }

        # Create analysis request
        user_message = f"""Analyze the dependencies for loading plugin '{target_plugin}'. 
Here are all registered plugins:
{json.dumps(plugin_data, indent=2)}

Please determine:
1. If there are any circular dependencies
2. The correct load order starting from '{target_plugin}'
3. Any missing or unmet dependencies
4. Whether it's safe to load '{target_plugin}'"""

        self.conversation_history.append({
            "role": "user",
            "content": user_message
        })

        # Get Claude's analysis
        response = self.client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            system=self.system_prompt,
            messages=self.conversation_history
        )

        assistant_message = response.content[0].text
        self.conversation_history.append({
            "role": "assistant",
            "content": assistant_message
        })

        # Parse the response
        try:
            # Extract JSON from response
            json_start = assistant_message.find('{')
            json_end = assistant_message.rfind('}') + 1
            if json_start >= 0 and json_end > json_start:
                json_str = assistant_message[json_start:json_end]
                analysis = json.loads(json_str)
            else:
                # If no JSON found, create a structured response based on text
                analysis = {
                    "valid": target_plugin in self.plugins and all(
                        dep in self.plugins for dep in self.plugins[target_plugin].dependencies
                    ),
                    "load_order": self._topological_sort([target_plugin]),
                    "circular_dependencies": [],
                    "missing_dependencies": [
                        dep for dep in self.plugins[target_plugin].dependencies
                        if dep not in self.plugins
                    ] if target_plugin in self.plugins else [],
                    "analysis": "Analysis completed"
                }
        except (json.JSONDecodeError, KeyError):
            # Fallback to simple dependency resolution
            analysis = {
                "valid": target_plugin in self.plugins,
                "load_order": self._topological_sort([target_plugin]),
                "circular_dependencies": [],
                "missing_dependencies": [],
                "analysis": "Using fallback analysis"
            }

        return analysis

    def _topological_sort(self, start_plugins: Optional[List[str]] = None) -> List[str]:
        """Perform topological sort to determine plugin load order."""
        if start_plugins is None:
            start_plugins = list(self.plugins.keys())

        # Build adjacency list and in-degree count
        in_degree = {name: 0 for name in self.plugins}
        adjacency = {name: [] for name in self.plugins}

        for name, plugin in self.plugins.items():
            for dep in plugin.dependencies:
                if dep in self.plugins:
                    adjacency[dep].append(name)
                    in_degree[name] += 1

        # Kahn's algorithm
        queue = [name for name in start_plugins if in_degree[name] == 0]
        result = []

        while queue:
            # Sort for deterministic output
            queue.sort()
            node = queue.pop(0)
            result.append(node)

            for neighbor in adjacency[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        # Check for cycles
        if len(result) != len(start_plugins):
            # Find nodes not in result (part of cycle)
            cycled = [n for n in start_plugins if n not in result]
            return result + cycled

        return result

    def _check_circular_dependencies(self) -> List[List[str]]:
        """Check for circular dependencies using Claude assistance."""
        # Build a simple dependency graph
        visited: Set[str] = set()
        cycles: List[List[str]] = []

        def dfs(node: str, path: List[str], rec_stack: Set[str]) -> None:
            visited.add(node)
            rec_stack.add(node)
            path.append(node)

            if node in self.plugins:
                for dep in self.plugins[node].dependencies:
                    if dep not in visited:
                        dfs(dep, path.copy(), rec_stack.copy())
                    elif dep in rec_stack:
                        # Found a cycle
                        cycle_start = path.index(dep)
                        cycle = path[cycle_start:] + [dep]
                        if cycle not in cycles:
                            cycles.append(cycle)

            rec_stack.discard(node)

        for plugin_name in self.plugins:
            if plugin_name not in visited:
                dfs(plugin_name, [], set())

        return cycles

    def load_plugin(self, plugin_name: str) -> bool:
        """
        Load a plugin and its dependencies in the correct order.
        Uses Claude to analyze and verify dependency order.
        """
        if plugin_name not in self.plugins:
            raise ValueError(f"Plugin '{plugin_name}' not found")

        if plugin_name in self.loaded_plugins:
            print(f"Plugin '{plugin_name}' is already loaded")
            return True

        # Get dependency analysis from Claude
        analysis = self._get_dependency_analysis(plugin_name)

        if not analysis.get("valid", False):
            missing = analysis.get("missing_dependencies", [])
            if missing:
                raise ValueError(f"Missing dependencies for '{plugin_name}': {missing}")
            circular = analysis.get("circular_dependencies", [])
            if circular:
                raise ValueError(f"Circular dependencies detected: {circular}")

        # Load plugins in the determined order
        load_order = analysis.get("load_order", [plugin_name])

        for plugin_to_load in load_order:
            if plugin_to_load in self.loaded_plugins:
                continue

            if plugin_to_load not in self.plugins:
                continue

            plugin = self.plugins[plugin_to_load]

            # Check dependencies are loaded
            for dep in plugin.dependencies:
                if dep not in self.loaded_plugins:
                    raise RuntimeError(
                        f"Dependency '{dep}' of '{plugin_to_load}' is not loaded"
                    )

            # Call on_load hook
            if plugin.on_load:
                try:
                    plugin.on_load()
                except Exception as e:
                    raise RuntimeError(
                        f"Error loading plugin '{plugin_to_load}': {str(e)}"
                    )

            self.loaded_plugins.add(plugin_to_load)
            print(f"Loaded plugin '{plugin_to_load}' v{plugin.version}")

        return True

    def unload_plugin(self, plugin_name: str) -> bool:
        """Unload a plugin and its dependents."""
        if plugin_name not in self.plugins:
            raise ValueError(f"Plugin '{plugin_name}' not found")

        if plugin_name not in self.loaded_plugins:
            print(f"Plugin '{plugin_name}' is not loaded")
            return True

        # Find and unload dependent plugins first
        dependents = [
            name for name, plugin in self.plugins.items()
            if plugin_name in plugin.dependencies and name in self.loaded_plugins
        ]

        for dependent in dependents:
            self.unload_plugin(dependent)

        # Unload the plugin
        plugin = self.plugins[plugin_name]
        if plugin.on_unload:
            try:
                plugin.on_unload()
            except Exception as e:
                raise RuntimeError(
                    f"Error unloading plugin '{plugin_name}': {str(e)}"
                )

        self.loaded_plugins.discard(plugin_name)
        print(f"Unloaded plugin '{plugin_name}'")

        return True

    def emit_event(self, event_name: str, data: Dict[str, Any] = None) -> None:
        """Emit an event to all loaded plugins."""
        if data is None:
            data = {}

        for plugin_name in self.loaded_plugins:
            plugin = self.plugins[plugin_name]
            if plugin.on_event:
                try:
                    plugin.on_event(event_name, data)
                except Exception as e:
                    print(f"Error in {plugin_name}.on_event: {str(e)}")

    def get_status(self) -> Dict[str, Any]:
        """Get the current status of all plugins."""
        return {
            "total_plugins": len(self.plugins),
            "loaded_plugins": len(self.loaded_plugins),
            "plugin_details": {
                name: {
                    "version": plugin.version,
                    "dependencies": plugin.dependencies,
                    "loaded": name in self.loaded_plugins
                }
                for name, plugin in self.plugins.items()
            }
        }

    def chat_about_plugins(self, question: str) -> str:
        """Have a conversation with Claude about the plugin system."""
        # Add context about current plugins
        plugin_status = self.get_status()
        context = f"""Current plugin system status:
{json.dumps(plugin_status, indent=2)}

User question: {question}"""

        self.conversation_history.append({
            "role": "user",
            "content": context
        })

        response = self.client.messages.create(
            model="claude-3-5-sonnet-20241022",
            max_tokens=1024,
            system=self.system_prompt,
            messages=self.conversation_history
        )

        assistant_message = response.content[0].text
        self.conversation_history.append({
            "role": "assistant",
            "content": assistant_message
        })

        return assistant_message


# Example usage and testing
def main():
    """Demonstrate the plugin management system."""
    manager = PluginManager()

    # Define some plugins with lifecycle hooks
    def logger_load():
        print("  -> Logger plugin initialized")

    def logger_unload():
        print("  -> Logger plugin cleaned up")

    def logger_event(event_name: str, data: Dict[str, Any]):
        print(f"  [LOG] Event: {event_name}, Data: {data}")

    logger_plugin = Plugin(
        name="logger",
        version="1.0.0",
        dependencies=[],
        on_load=logger_load,
        on_unload=logger_unload,
        on_event=logger_event
    )

    def database_load():
        print("  -> Database connection established")

    def database_unload():
        print("  -> Database connection closed")

    def database_event(event_name: str, data: Dict[str, Any]):
        if event_name == "save":
            print(f"  [DB] Saving: {data}")

    database_plugin = Plugin(
        name="database",
        version="2.0.0",
        dependencies=["logger"],
        on_load=database_load,
        on_unload=database_unload,
        on_event=database_event
    )

    def api_load():
        print("  -> API server started")

    def api_unload():
        print("  -> API server stopped")

    def api_event(event_name: str, data: Dict[str, Any]):
        if event_name == "request":
            print(f"  [API] Request received: {data}")

    api_plugin = Plugin(
        name="api",
        version="1.5.0",
        dependencies=["database", "logger"],
        on_load=api_load,
        on_unload=api_unload,
        on_event=api_event
    )

    # Register plugins
    print("Registering plugins...")
