    manager.register_plugin(database_plugin)
    manager.register_plugin(api_plugin)

    # Check status
    print("\nPlugin System Status:")
    status = manager.get_status()
    print(f"Total plugins: {status['total_plugins']}")
    print(f"Loaded plugins: {status['loaded_plugins']}")

    # Load plugins with dependency resolution
    print("\nLoading API plugin (with dependencies)...")
    try:
        manager.load_plugin("api")
    except Exception as e:
        print(f"Error: {e}")

    # Emit events
    print("\nEmitting events...")
    manager.emit_event("request", {"path": "/api/users", "method": "GET"})
    manager.emit_event("save", {"table": "users", "record": {"id": 1, "name": "John"}})

    # Chat with Claude about plugins
    print("\nAsking Claude about plugin configuration...")
    response = manager.chat_about_plugins(
        "What is the optimal plugin load sequence and why?"
    )
    print(f"Claude's response:\n{response}\n")

    # Unload plugins
    print("Unloading plugins...")
    manager.unload_plugin("api")

    print("\nFinal plugin status:")
    status = manager.get_status()
    for name, details in status['plugin_details'].items():
        print(f"  {name}: loaded={details['loaded']}")


if __name__ == "__main__":
    main()
