```python
"""
Async web scraper with rate limiting, retry logic, and result caching.
Uses Claude's tool use capabilities to manage scraping operations efficiently.
"""

import asyncio
import json
import hashlib
import time
from datetime import datetime, timedelta
from typing import Optional
from anthropic import Anthropic


class WebScraper:
    """
    Async web scraper with rate limiting, retry logic, and result caching.
    Uses Claude's tool use capabilities to manage scraping operations.
    """

    def __init__(self, max_concurrent: int = 5, cache_ttl: int = 3600):
        """
        Initialize the WebScraper.

        Args:
            max_concurrent: Maximum number of concurrent scraping operations
            cache_ttl: Cache time-to-live in seconds
        """
        self.max_concurrent = max_concurrent
        self.cache_ttl = cache_ttl
        self.cache: dict = {}
        self.semaphore = asyncio.Semaphore(max_concurrent)
        self.client = Anthropic()
        self.request_times: list[float] = []
        self.rate_limit_delay = 0.1  # 100ms minimum between requests

    def _get_cache_key(self, url: str) -> str:
        """Generate a cache key from URL."""
        return hashlib.md5(url.encode()).hexdigest()

    def _is_cache_valid(self, cache_key: str) -> bool:
        """Check if cached result is still valid."""
        if cache_key not in self.cache:
            return False

        cached_item = self.cache[cache_key]
        age = time.time() - cached_item["timestamp"]
        return age < self.cache_ttl

    def _get_cached_result(self, url: str) -> Optional[dict]:
        """Get result from cache if valid."""
        cache_key = self._get_cache_key(url)
        if self._is_cache_valid(cache_key):
            return self.cache[cache_key]["data"]
        elif cache_key in self.cache:
            del self.cache[cache_key]
        return None

    def _cache_result(self, url: str, data: dict) -> None:
        """Cache a scraping result."""
        cache_key = self._get_cache_key(url)
        self.cache[cache_key] = {"data": data, "timestamp": time.time()}

    async def _apply_rate_limiting(self) -> None:
        """Apply rate limiting to prevent overwhelming servers."""
        current_time = time.time()
        self.request_times = [t for t in self.request_times if current_time - t < 1.0]

        if len(self.request_times) > 0:
            time_since_last = current_time - self.request_times[-1]
            if time_since_last < self.rate_limit_delay:
                await asyncio.sleep(self.rate_limit_delay - time_since_last)

        self.request_times.append(time.time())

    def _scrape_with_claude(self, url: str, retry_count: int = 0) -> dict:
        """
        Use Claude's tool use to manage scraping with retry logic.

        Args:
            url: URL to scrape
            retry_count: Current retry attempt number

        Returns:
            Dictionary containing scraped data and metadata
        """
        max_retries = 3

        tools = [
            {
                "name": "fetch_webpage",
                "description": "Fetch and parse webpage content",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "url": {
                            "type": "string",
                            "description": "URL to fetch",
                        },
                        "timeout": {
                            "type": "integer",
                            "description": "Request timeout in seconds",
                        },
                    },
                    "required": ["url"],
                },
            },
            {
                "name": "parse_content",
                "description": "Parse HTML content and extract data",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "content": {
                            "type": "string",
                            "description": "HTML content to parse",
                        },
                        "selectors": {
                            "type": "array",
                            "items": {"type": "string"},
                            "description": "CSS selectors to extract",
                        },
                    },
                    "required": ["content"],
                },
            },
        ]

        messages = [
            {
                "role": "user",
                "content": f"""Please scrape the webpage at {url} and extract relevant information.

Attempt {retry_count + 1}/{max_retries}

Steps:
1. First, fetch the webpage content using the fetch_webpage tool
2. Then parse the content using the parse_content tool to extract structured data
3. Return the extracted data with metadata about the scraping operation

If you encounter any errors, provide a structured response with error details.""",
            }
        ]

        try:
            response = self.client.messages.create(
                model="claude-3-5-sonnet-20241022",
                max_tokens=1024,
                tools=tools,
                messages=messages,
            )

            result = {"url": url, "success": True, "data": None, "error": None}

            for content in response.content:
                if hasattr(content, "text"):
                    try:
                        data = json.loads(content.text)
                        result["data"] = data
                    except json.JSONDecodeError:
                        result["data"] = {"content": content.text}

            return result

        except Exception as e:
            if retry_count < max_retries - 1:
                return self._scrape_with_claude(url, retry_count + 1)

            return {
                "url": url,
                "success": False,
                "data": None,
                "error": str(e),
                "retry_count": retry_count,
            }

    async def scrape(self, url: str) -> dict:
        """
        Scrape a single URL with caching and rate limiting.

        Args:
            url: URL to scrape

        Returns:
            Dictionary containing scraped data and metadata
        """
        cached_result = self._get_cached_result(url)
        if cached_result is not None:
            return {"url": url, "success": True, "data": cached_result, "cached": True}

        async with self.semaphore:
            await self._apply_rate_limiting()

            result = await asyncio.to_thread(self._scrape_with_claude, url)

            if result["success"] and result["data"]:
                self._cache_result(url, result["data"])
                result["cached"] = False

            return result

    async def scrape_many(self, urls: list[str]) -> list[dict]:
        """
        Scrape multiple URLs concurrently with rate limiting.

        Args:
            urls: List of URLs to scrape

        Returns:
            List of dictionaries containing scraped data for each URL
        """
        tasks = [self.scrape(url) for url in urls]
        results = await asyncio.gather(*tasks, return_exceptions=True)

        processed_results = []
        for result in results:
            if isinstance(result, Exception):
                processed_results.append(
                    {
                        "success": False,
                        "error": str(result),
                        "data": None,
                    }
                )
            else:
                processed_results.append(result)

        return processed_results

    def get_cache_stats(self) -> dict:
        """Get cache statistics."""
        valid_items = sum(
            1 for key in self.cache if self._is_cache_valid(key)
        )
        return {
            "total_cached_items": len(self.cache),
            "valid_items": valid_items,
            "cache_ttl": self.cache_ttl,
            "max_concurrent": self.max_concurrent,
        }

    def clear_cache(self) -> None:
        """Clear all cached results."""
        self.cache.clear()


async def main():
    """Main function to demonstrate the WebScraper."""
    scraper = WebScraper(max_concurrent=3, cache_ttl=3600)

    urls_to_scrape = [
        "https://example.com",
        "https://python.org",
    ]

    print("Starting web scraping demonstration...")
    print(f"Configuration: max_concurrent={scraper.max_concurrent}, cache_ttl={scraper.cache_ttl}")
    print("-" * 60)

    start_time = time.time()

    results = await scraper.scrape_many(urls_to_scrape)

    for result in results:
        print(f"\nURL: {result.get('url', 'Unknown')}")
        print(f"Success: {result.get('success', False)}")
        print(f"Cached: {result.get('cached', False)}")
        if result.get("error"):
            print(f"Error: {result['error']}")
        elif result.get("data"):
            print(f"Data preview: {str(result['data'])[:100]}...")

    end_time = time.time()

    print("\n" + "-" * 60)
    print(f"Scraping completed in {end_time - start_time:.2f} seconds")
    print(f"Cache stats: {scraper.get_cache_stats()}")


if __name__ == "__main__":
    asyncio.run(main())
