"""
CQRS Mediator Implementation

This module provides a Command Query Responsibility Segregation (CQRS) pattern
implementation with a mediator that routes commands and queries to their
respective handlers, with built-in validation support.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, Generic, List, Type, TypeVar


# ---------------------------------------------------------------------------
# Type variables
# ---------------------------------------------------------------------------
TCommand = TypeVar("TCommand", bound="Command")
TQuery = TypeVar("TQuery", bound="Query")
TResult = TypeVar("TResult")


# ---------------------------------------------------------------------------
# Exceptions
# ---------------------------------------------------------------------------
class MediatorError(Exception):
    """Base exception for mediator-related errors."""


class HandlerNotFoundError(MediatorError):
    """Raised when no handler is registered for a given command or query."""


class HandlerAlreadyRegisteredError(MediatorError):
    """Raised when attempting to register a duplicate handler."""


class ValidationError(MediatorError):
    """Raised when command validation fails."""

    def __init__(self, errors: List[str]) -> None:
        self.errors = errors
        super().__init__("Validation failed: " + "; ".join(errors))


# ---------------------------------------------------------------------------
# Base message types
# ---------------------------------------------------------------------------
@dataclass
class Command(ABC):
    """
    Base class for all commands.

    Commands represent an intent to change state. They may return a result
    (e.g., the ID of a newly created entity), but their primary purpose is
    to mutate state.

    Subclasses should override `validate` to enforce business invariants.
    """

    def validate(self) -> List[str]:
        """
        Validate the command and return a list of error messages.

        An empty list indicates the command is valid.
        """
        return []


@dataclass
class Query(ABC):
    """
    Base class for all queries.

    Queries represent a request for data and must not mutate state.
    """


# ---------------------------------------------------------------------------
# Handler interfaces
# ---------------------------------------------------------------------------
class CommandHandler(ABC, Generic[TCommand, TResult]):
    """Abstract base class for command handlers."""

    @abstractmethod
    def handle(self, command: TCommand) -> TResult:
        """Process the given command and optionally return a result."""
        raise NotImplementedError


class QueryHandler(ABC, Generic[TQuery, TResult]):
    """Abstract base class for query handlers."""

    @abstractmethod
    def handle(self, query: TQuery) -> TResult:
        """Process the given query and return its result."""
        raise NotImplementedError


# ---------------------------------------------------------------------------
# Mediator
# ---------------------------------------------------------------------------
class Mediator:
    """
    Routes commands and queries to their registered handlers.

    Commands are validated before being dispatched. Middleware callables can
    be registered to wrap command/query execution (e.g., for logging).
    """

    def __init__(self) -> None:
        self._command_handlers: Dict[Type[Command], CommandHandler] = {}
        self._query_handlers: Dict[Type[Query], QueryHandler] = {}

    # -- Registration -------------------------------------------------------
    def register_command_handler(
        self, command_type: Type[TCommand], handler: CommandHandler[TCommand, Any]
    ) -> None:
        """Register a handler for a specific command type."""
        if command_type in self._command_handlers:
            raise HandlerAlreadyRegisteredError(
                f"Handler already registered for command {command_type.__name__}"
            )
        self._command_handlers[command_type] = handler

    def register_query_handler(
        self, query_type: Type[TQuery], handler: QueryHandler[TQuery, Any]
    ) -> None:
        """Register a handler for a specific query type."""
        if query_type in self._query_handlers:
            raise HandlerAlreadyRegisteredError(
                f"Handler already registered for query {query_type.__name__}"
            )
        self._query_handlers[query_type] = handler

    # -- Dispatch -----------------------------------------------------------
    def send(self, command: Command) -> Any:
        """
        Validate and dispatch a command to its handler.

        Raises:
            ValidationError: If the command fails validation.
            HandlerNotFoundError: If no handler is registered.
        """
        if not isinstance(command, Command):
            raise TypeError(f"Expected Command, got {type(command).__name__}")

        errors = command.validate()
        if errors:
            raise ValidationError(errors)

        handler = self._command_handlers.get(type(command))
        if handler is None:
            raise HandlerNotFoundError(
                f"No handler registered for command {type(command).__name__}"
            )

        return handler.handle(command)

    def query(self, query: Query) -> Any:
        """
        Dispatch a query to its handler and return the result.

        Raises:
            HandlerNotFoundError: If no handler is registered.
        """
        if not isinstance(query, Query):
            raise TypeError(f"Expected Query, got {type(query).__name__}")

        handler = self._query_handlers.get(type(query))
        if handler is None:
            raise HandlerNotFoundError(
                f"No handler registered for query {type(query).__name__}"
            )

        return handler.handle(query)


# ---------------------------------------------------------------------------
# Example usage
# ---------------------------------------------------------------------------
if __name__ == "__main__":
    # --- Domain state (in-memory) -----------------------------------------
    _users: Dict[int, Dict[str, Any]] = {}
    _next_id: List[int] = [1]

    # --- Commands ---------------------------------------------------------
    @dataclass
    class CreateUserCommand(Command):
        name: str
        email: str

        def validate(self) -> List[str]:
            errors: List[str] = []
            if not self.name or not self.name.strip():
                errors.append("name is required")
            if "@" not in self.email:
                errors.append("email must be valid")
            return errors

    @dataclass
    class DeleteUserCommand(Command):
        user_id: int

        def validate(self) -> List[str]:
            return [] if self.user_id > 0 else ["user_id must be positive"]

    # --- Queries ----------------------------------------------------------
    @dataclass
    class GetUserQuery(Query):
        user_id: int

    @dataclass
    class ListUsersQuery(Query):
        pass

    # --- Handlers ---------------------------------------------------------
    class CreateUserHandler(CommandHandler[CreateUserCommand, int]):
        def handle(self, command: CreateUserCommand) -> int:
            user_id = _next_id[0]
            _next_id[0] += 1
            _users[user_id] = {"id": user_id, "name": command.name, "email": command.email}
            return user_id

    class DeleteUserHandler(CommandHandler[DeleteUserCommand, bool]):
        def handle(self, command: DeleteUserCommand) -> bool:
            return _users.pop(command.user_id, None) is not None

    class GetUserHandler(QueryHandler[GetUserQuery, Dict[str, Any]]):
        def handle(self, query: GetUserQuery) -> Dict[str, Any]:
            return _users.get(query.user_id, {})

    class ListUsersHandler(QueryHandler[ListUsersQuery, List[Dict[str, Any]]]):
        def handle(self, query: ListUsersQuery) -> List[Dict[str, Any]]:
            return list(_users.values())

    # --- Wire up the mediator --------------------------------------------
    mediator = Mediator()
    mediator.register_command_handler(CreateUserCommand, CreateUserHandler())
    mediator.register_command_handler(DeleteUserCommand, DeleteUserHandler())
    mediator.register_query_handler(GetUserQuery, GetUserHandler())
    mediator.register_query_handler(ListUsersQuery, ListUsersHandler())

    # --- Use it -----------------------------------------------------------
    alice_id = mediator.send(CreateUserCommand(name="Alice", email="alice@example.com"))
    bob_id = mediator.send(CreateUserCommand(name="Bob", email="bob@example.com"))

    print("Alice:", mediator.query(GetUserQuery(user_id=alice_id)))
    print("All users:", mediator.query(ListUsersQuery()))

    mediator.send(DeleteUserCommand(user_id=bob_id))
    print("After delete:", mediator.query(ListUsersQuery()))

    # Validation failure
    try:
        mediator.send(CreateUserCommand(name="", email="bad"))
    except ValidationError as e:
        print("Validation errors:", e.errors)
```

