"""
Plugin system with lifecycle hooks and dependency management.

This module provides a :class:`PluginManager` that loads, unloads, and dispatches
events to plugins while enforcing dependency ordering via topological sort.
"""

from __future__ import annotations

import logging
from abc import ABC, abstractmethod
from collections import defaultdict, deque
from typing import Any, Dict, Iterable, List, Optional, Set

logger = logging.getLogger(__name__)


class PluginError(Exception):
    """Base class for all plugin-related errors."""


class DependencyError(PluginError):
    """Raised when a dependency is missing or cycles are detected."""


class PluginStateError(PluginError):
    """Raised when an operation is invalid given the plugin's current state."""


class Plugin(ABC):
    """
    Abstract base class for plugins.

    Subclasses must define ``name`` and ``version`` class attributes (or
    instance attributes) and implement the lifecycle hooks.
    """

    #: Unique plugin name.
    name: str = ""
    #: Plugin version string (e.g. ``"1.0.0"``).
    version: str = "0.0.0"
    #: Names of plugins this plugin depends on.
    dependencies: List[str] = []

    @abstractmethod
    def on_load(self, manager: "PluginManager") -> None:
        """Called when the plugin is loaded. Initialize resources here."""

    @abstractmethod
    def on_unload(self, manager: "PluginManager") -> None:
        """Called when the plugin is unloaded. Release resources here."""

    @abstractmethod
    def on_event(self, event: str, *args: Any, **kwargs: Any) -> Any:
        """Called when an event is dispatched to the plugin."""

    def __repr__(self) -> str:  # pragma: no cover - trivial
        return f"<Plugin {self.name} v{self.version}>"


class PluginManager:
    """
    Manages plugin registration, loading, unloading, and event dispatch.

    Plugins are loaded in dependency order (dependencies first) and unloaded
    in reverse order. Events are dispatched to loaded plugins in load order.
    """

    def __init__(self) -> None:
        self._plugins: Dict[str, Plugin] = {}
        self._loaded: Dict[str, Plugin] = {}
        self._load_order: List[str] = []

    # ------------------------------------------------------------------ #
    # Registration
    # ------------------------------------------------------------------ #
    def register(self, plugin: Plugin) -> None:
        """Register a plugin instance. Does not load it."""
        if not plugin.name:
            raise PluginError("Plugin must have a non-empty name.")
        if plugin.name in self._plugins:
            raise PluginError(f"Plugin '{plugin.name}' is already registered.")
        self._plugins[plugin.name] = plugin
        logger.debug("Registered plugin %s v%s", plugin.name, plugin.version)

    def unregister(self, name: str) -> None:
        """Unregister a plugin (must be unloaded first)."""
        if name in self._loaded:
            raise PluginStateError(
                f"Plugin '{name}' is currently loaded; unload it first."
            )
        if name not in self._plugins:
            raise PluginError(f"Plugin '{name}' is not registered.")
        del self._plugins[name]

    # ------------------------------------------------------------------ #
    # Introspection
    # ------------------------------------------------------------------ #
    @property
    def plugins(self) -> Dict[str, Plugin]:
        """Return a copy of all registered plugins."""
        return dict(self._plugins)

    @property
    def loaded(self) -> List[str]:
        """Return the list of currently loaded plugin names in load order."""
        return list(self._load_order)

    def get(self, name: str) -> Optional[Plugin]:
        """Return a registered plugin by name, or ``None``."""
        return self._plugins.get(name)

    def is_loaded(self, name: str) -> bool:
        """Return True if a plugin is currently loaded."""
        return name in self._loaded

    # ------------------------------------------------------------------ #
    # Dependency resolution
    # ------------------------------------------------------------------ #
    def _resolve_order(self, names: Iterable[str]) -> List[str]:
        """
        Compute a topological load order for the given plugin names,
        including transitive dependencies. Raises on missing deps or cycles.
        """
        target: Set[str] = set()
        stack = list(names)
        while stack:
            n = stack.pop()
            if n in target:
                continue
            if n not in self._plugins:
                raise DependencyError(f"Unknown plugin '{n}'.")
            target.add(n)
            stack.extend(self._plugins[n].dependencies)

        # Kahn's algorithm (deterministic by sorting).
        in_degree: Dict[str, int] = {n: 0 for n in target}
        graph: Dict[str, List[str]] = defaultdict(list)
        for n in target:
            for dep in self._plugins[n].dependencies:
                graph[dep].append(n)
                in_degree[n] += 1

        ready = deque(sorted(n for n, d in in_degree.items() if d == 0))
        order: List[str] = []
        while ready:
            n = ready.popleft()
            order.append(n)
            for nxt in sorted(graph[n]):
                in_degree[nxt] -= 1
                if in_degree[nxt] == 0:
                    ready.append(nxt)

        if len(order) != len(target):
            remaining = [n for n, d in in_degree.items() if d > 0]
            raise DependencyError(
                f"Dependency cycle detected among: {sorted(remaining)}"
            )
        return order

    # ------------------------------------------------------------------ #
    # Lifecycle
    # ------------------------------------------------------------------ #
    def load(self, name: str) -> None:
        """Load a single plugin and any required dependencies."""
        self.load_many([name])

    def load_many(self, names: Iterable[str]) -> None:
        """Load multiple plugins, resolving dependencies."""
        order = self._resolve_order(names)
        for n in order:
            if n in self._loaded:
                continue
            plugin = self._plugins[n]
            logger.info("Loading plugin %s v%s", plugin.name, plugin.version)
            try:
                plugin.on_load(self)
            except Exception as exc:
                raise PluginError(
                    f"Error loading plugin '{n}': {exc}"
                ) from exc
            self._loaded[n] = plugin
            self._load_order.append(n)

    def load_all(self) -> None:
        """Load every registered plugin in dependency order."""
        self.load_many(list(self._plugins))

    def unload(self, name: str) -> None:
        """
        Unload a plugin. Fails if other loaded plugins depend on it.
        """
        if name not in self._loaded:
            raise PluginStateError(f"Plugin '{name}' is not loaded.")

        dependents = [
            other
            for other in self._loaded
            if name in self._plugins[other].dependencies
        ]
        if dependents:
            raise DependencyError(
                f"Cannot unload '{name}'; required by: {dependents}"
            )

        plugin = self._loaded[name]
        logger.info("Unloading plugin %s", name)
        try:
            plugin.on_unload(self)
        except Exception as exc:
            raise PluginError(
                f"Error unloading plugin '{name}': {exc}"
            ) from exc
        finally:
            del self._loaded[name]
            self._load_order.remove(name)

    def unload_all(self) -> None:
        """Unload all plugins in reverse load order."""
        for name in reversed(list(self._load_order)):
            try:
                self.unload(name)
            except Exception:
                logger.exception("Failed to unload %s", name)

    # ------------------------------------------------------------------ #
    # Event dispatch
    # ------------------------------------------------------------------ #
    def dispatch(self, event: str, *args: Any, **kwargs: Any) -> Dict[str, Any]:
        """
        Dispatch an event to all loaded plugins in load order.

        Returns a mapping of plugin name -> return value. Exceptions are
        logged and captured as the result value for that plugin.
        """
        results: Dict[str, Any] = {}
        for name in self._load_order:
            plugin = self._loaded[name]
            try:
                results[name] = plugin.on_event(event, *args, **kwargs)
            except Exception as exc:
                logger.exception(
                    "Plugin '%s' raised during event '%s'", name, event
                )
                results[name] = exc
        return results

    # ------------------------------------------------------------------ #
    # Context manager support
    # ------------------------------------------------------------------ #
    def __enter__(self) -> "PluginManager":
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.unload_all()


__all__ = [
    "Plugin",
    "PluginManager",
    "PluginError",
    "DependencyError",
    "PluginStateError",
]
