class Pipeline:
    def __init__(self):
        self.middlewares = []

    def use(self, middleware_fn):
        """
        Adds a middleware function to the pipeline.
        """
        self.middlewares.append(middleware_fn)

    def _execute_middlewares(self, request, index=0):
        """
        Internal method to execute middleware functions in sequence.
        """
        if index < len(self.middlewares):
            middleware = self.middlewares[index]
            return middleware(request, lambda req: self._execute_middlewares(req, index + 1))
        return request

    def execute(self, request):
        """
        Executes the middleware pipeline and returns the final response.
        """
        return self._execute_middlewares(request)
