"""
CQRS Mediator Implementation

A clean, production-ready Command Query Responsibility Segregation (CQRS)
pattern implementation with a Mediator that routes commands and queries
to their respective handlers, with built-in validation support.
"""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import (
    Any,
    Callable,
    Dict,
    Generic,
    List,
    Type,
    TypeVar,
)


# ---------------------------------------------------------------------------
# Exceptions
# ---------------------------------------------------------------------------


class MediatorError(Exception):
    """Base exception for mediator-related errors."""


class HandlerNotRegisteredError(MediatorError):
    """Raised when no handler is registered for a command or query."""


class HandlerAlreadyRegisteredError(MediatorError):
    """Raised when attempting to register a duplicate handler."""


class ValidationError(MediatorError):
    """Raised when command/query validation fails."""

    def __init__(self, errors: List[str]) -> None:
        self.errors = errors
        super().__init__(f"Validation failed: {', '.join(errors)}")


# ---------------------------------------------------------------------------
# Core CQRS Abstractions
# ---------------------------------------------------------------------------


TResult = TypeVar("TResult")


@dataclass
class Command(ABC):
    """
    Base class for all commands.

    Commands represent an intent to change system state. They may return
    a result (e.g., the ID of a newly-created entity) but are primarily
    used for write operations.

    Subclasses can override ``validate`` to provide custom validation logic.
    """

    def validate(self) -> List[str]:
        """
        Validate the command and return a list of error messages.

        An empty list indicates the command is valid.
        Override this method in subclasses to implement validation rules.
        """
        return []


@dataclass
class Query(ABC, Generic[TResult]):
    """
    Base class for all queries.

    Queries represent a request for data. They must not modify system state.
    The generic parameter ``TResult`` describes the expected return type.
    """

    def validate(self) -> List[str]:
        """Validate the query and return a list of error messages."""
        return []


TCommand = TypeVar("TCommand", bound=Command)
TQuery = TypeVar("TQuery", bound=Query)


class CommandHandler(ABC, Generic[TCommand, TResult]):
    """
    Base class for command handlers.

    Each command type should have exactly one handler responsible for
    executing the state-changing logic associated with that command.
    """

    @abstractmethod
    def handle(self, command: TCommand) -> TResult:
        """Execute the command and return its result."""
        raise NotImplementedError


class QueryHandler(ABC, Generic[TQuery, TResult]):
    """
    Base class for query handlers.

    Each query type should have exactly one handler responsible for
    fetching and returning the requested data.
    """

    @abstractmethod
    def handle(self, query: TQuery) -> TResult:
        """Execute the query and return its result."""
        raise NotImplementedError


# ---------------------------------------------------------------------------
# Mediator
# ---------------------------------------------------------------------------


@dataclass
class Mediator:
    """
    Routes commands and queries to their registered handlers.

    The mediator centralizes dispatching logic so that senders are decoupled
    from handlers. It performs validation before dispatching and supports
    pipeline behaviors (middleware) for cross-cutting concerns such as
    logging, caching, or transactional boundaries.
    """

    _command_handlers: Dict[Type[Command], CommandHandler] = field(
        default_factory=dict
    )
    _query_handlers: Dict[Type[Query], QueryHandler] = field(default_factory=dict)
    _middleware: List[Callable[[Any, Callable[[Any], Any]], Any]] = field(
        default_factory=list
    )

    # -- Registration --------------------------------------------------------

    def register_command_handler(
        self, command_type: Type[Command], handler: CommandHandler
    ) -> None:
        """Register a handler for a specific command type."""
        if command_type in self._command_handlers:
            raise HandlerAlreadyRegisteredError(
                f"Handler already registered for command {command_type.__name__}"
            )
        if not isinstance(handler, CommandHandler):
            raise TypeError("Handler must inherit from CommandHandler")
        self._command_handlers[command_type] = handler

    def register_query_handler(
        self, query_type: Type[Query], handler: QueryHandler
    ) -> None:
        """Register a handler for a specific query type."""
        if query_type in self._query_handlers:
            raise HandlerAlreadyRegisteredError(
                f"Handler already registered for query {query_type.__name__}"
            )
        if not isinstance(handler, QueryHandler):
            raise TypeError("Handler must inherit from QueryHandler")
        self._query_handlers[query_type] = handler

    def use(
        self, middleware: Callable[[Any, Callable[[Any], Any]], Any]
    ) -> None:
        """
        Add a middleware function to the dispatch pipeline.

        Middleware signature: ``(message, next_callable) -> result``
        where ``next_callable(message)`` invokes the next step.
        """
        self._middleware.append(middleware)

    # -- Dispatch ------------------------------------------------------------

    def send(self, command: Command) -> Any:
        """
        Dispatch a command to its registered handler.

        Validates the command before dispatching. Raises ``ValidationError``
        if validation fails, or ``HandlerNotRegisteredError`` if no handler
        is registered.
        """
        if not isinstance(command, Command):
            raise TypeError("send() requires a Command instance")

        self._validate(command)

        handler = self._command_handlers.get(type(command))
        if handler is None:
            raise HandlerNotRegisteredError(
                f"No handler registered for command {type(command).__name__}"
            )

        return self._invoke_pipeline(command, handler.handle)

    def query(self, query: Query[TResult]) -> TResult:
        """
        Dispatch a query to its registered handler.

        Validates the query before dispatching. Raises ``ValidationError``
        if validation fails, or ``HandlerNotRegisteredError`` if no handler
        is registered.
        """
        if not isinstance(query, Query):
            raise TypeError("query() requires a Query instance")

        self._validate(query)

        handler = self._query_handlers.get(type(query))
        if handler is None:
            raise HandlerNotRegisteredError(
                f"No handler registered for query {type(query).__name__}"
            )

        return self._invoke_pipeline(query, handler.handle)

    # -- Internals -----------------------------------------------------------

    @staticmethod
    def _validate(message: Command | Query) -> None:
        errors = message.validate()
        if errors:
            raise ValidationError(errors)

    def _invoke_pipeline(
        self, message: Any, terminal: Callable[[Any], Any]
    ) -> Any:
        """Run registered middleware and finally invoke the handler."""
        pipeline: Callable[[Any], Any] = terminal
        for mw in reversed(self._middleware):
            next_fn = pipeline

            def wrapper(msg: Any, _mw=mw, _next=next_fn) -> Any:
                return _mw(msg, _next)

            pipeline = wrapper
        return pipeline(message)


# ---------------------------------------------------------------------------
# Example Usage
# ---------------------------------------------------------------------------


if __name__ == "__main__":
    # --- Define domain commands and queries ---

    @dataclass
    class CreateUserCommand(Command):
        username: str
        email: str

        def validate(self) -> List[str]:
            errors: List[str] = []
            if not self.username or len(self.username) < 3:
                errors.append("username must be at least 3 characters")
            if "@" not in self.email:
                errors.append("email must be valid")
            return errors

    @dataclass
    class GetUserQuery(Query[dict]):
        user_id: int

        def validate(self) -> List[str]:
            return [] if self.user_id > 0 else ["user_id must be positive"]

    # --- Define handlers ---

    class CreateUserHandler(CommandHandler[CreateUserCommand, int]):
        def __init__(self) -> None:
            self._users: Dict[int, dict] = {}
            self._next_id = 1

        def handle(self, command: CreateUserCommand) -> int:
            user_id = self._next_id
            self._users[user_id] = {
                "id": user_id,
                "username": command.username,
                "email": command.email,
            }
            self._next_id += 1
            return user_id

    class GetUserHandler(QueryHandler[GetUserQuery, dict]):
        def __init__(self, store: Dict[int, dict]) -> None:
            self._store = store

        def handle(self, query: GetUserQuery) -> dict:
            return self._store.get(query.user_id, {})

    # --- Wire up the mediator ---

    mediator = Mediator()
    create_handler = CreateUserHandler()
    mediator.register_command_handler(CreateUserCommand, create_handler)
    mediator.register_query_handler(
        GetUserQuery, GetUserHandler(create_handler._users)
    )

    # Simple logging middleware
    def logging_middleware(message: Any, next_fn: Callable[[Any], Any]) -> Any:
        print(f"[LOG] Dispatching {type(message).__name__}: {message}")
        result = next_fn(message)
        print(f"[LOG] Result: {result}")
        return result

    mediator.use(logging_middleware)

    # --- Use it ---
    new_id = mediator.send(CreateUserCommand(username="alice", email="a@b.com"))
    user = mediator.query(GetUserQuery(user_id=new_id))
    print("Fetched:", user)

    # Validation failure
    try:
        mediator.send(CreateUserCommand(username="x", email="bad"))
    except ValidationError as e:
        print("Validation failed as expected:", e.errors)
