"""
Plugin system with lifecycle hooks and dependency management.

This module provides a ``PluginManager`` class that handles registering,
loading, unloading, and event dispatch for plugins while enforcing
dependency ordering via topological sort.
"""

from __future__ import annotations

import logging
from abc import ABC, abstractmethod
from collections import defaultdict, deque
from typing import Any, Dict, Iterable, List, Optional, Set

logger = logging.getLogger(__name__)


class PluginError(Exception):
    """Base exception for plugin-related errors."""


class DependencyError(PluginError):
    """Raised when plugin dependencies cannot be resolved."""


class PluginNotFoundError(PluginError):
    """Raised when a referenced plugin is not registered."""


class Plugin(ABC):
    """
    Base class for all plugins.

    Subclasses must define ``name`` and ``version`` (either as class
    attributes or instance attributes) and may optionally declare a list
    of plugin-name dependencies via ``dependencies``.
    """

    name: str = ""
    version: str = "0.0.0"
    dependencies: List[str] = []

    @abstractmethod
    def on_load(self, manager: "PluginManager") -> None:
        """Called when the plugin is loaded. Perform setup here."""

    @abstractmethod
    def on_unload(self, manager: "PluginManager") -> None:
        """Called when the plugin is unloaded. Perform teardown here."""

    def on_event(self, event: str, *args: Any, **kwargs: Any) -> Any:
        """
        Called when an event is dispatched. Override to handle events.

        Return value is collected by the dispatcher. Default no-op.
        """
        return None

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"<Plugin {self.name} v{self.version}>"


class PluginManager:
    """
    Manages plugin registration, lifecycle, and event dispatch.

    Plugins are loaded in dependency order (a dependency is always loaded
    before its dependents) and unloaded in reverse order.
    """

    def __init__(self) -> None:
        self._plugins: Dict[str, Plugin] = {}
        self._loaded: Dict[str, Plugin] = {}
        self._load_order: List[str] = []

    # ------------------------------------------------------------------
    # Registration
    # ------------------------------------------------------------------
    def register(self, plugin: Plugin) -> None:
        """Register a plugin instance. Does not load it."""
        if not isinstance(plugin, Plugin):
            raise TypeError(f"Expected Plugin instance, got {type(plugin).__name__}")
        if not plugin.name:
            raise PluginError("Plugin must define a non-empty name")
        if plugin.name in self._plugins:
            raise PluginError(f"Plugin '{plugin.name}' is already registered")
        self._plugins[plugin.name] = plugin
        logger.debug("Registered plugin %s v%s", plugin.name, plugin.version)

    def unregister(self, name: str) -> None:
        """Unregister a plugin. It must not be loaded."""
        if name in self._loaded:
            raise PluginError(f"Cannot unregister loaded plugin '{name}'")
        if name not in self._plugins:
            raise PluginNotFoundError(name)
        del self._plugins[name]

    # ------------------------------------------------------------------
    # Dependency resolution
    # ------------------------------------------------------------------
    def _resolve_order(self, names: Iterable[str]) -> List[str]:
        """
        Return ``names`` (plus all transitive dependencies) in a valid
        load order using Kahn's algorithm. Raises DependencyError on
        missing deps or cycles.
        """
        wanted: Set[str] = set()
        stack = list(names)
        while stack:
            n = stack.pop()
            if n in wanted:
                continue
            if n not in self._plugins:
                raise PluginNotFoundError(f"Unknown plugin: '{n}'")
            wanted.add(n)
            stack.extend(self._plugins[n].dependencies)

        # Build graph restricted to wanted nodes.
        in_degree: Dict[str, int] = {n: 0 for n in wanted}
        edges: Dict[str, List[str]] = defaultdict(list)
        for n in wanted:
            for dep in self._plugins[n].dependencies:
                edges[dep].append(n)
                in_degree[n] += 1

        queue: deque[str] = deque(sorted(n for n, d in in_degree.items() if d == 0))
        order: List[str] = []
        while queue:
            node = queue.popleft()
            order.append(node)
            for nxt in sorted(edges[node]):
                in_degree[nxt] -= 1
                if in_degree[nxt] == 0:
                    queue.append(nxt)

        if len(order) != len(wanted):
            remaining = [n for n, d in in_degree.items() if d > 0]
            raise DependencyError(
                f"Circular dependency detected among: {remaining}"
            )
        return order

    # ------------------------------------------------------------------
    # Lifecycle
    # ------------------------------------------------------------------
    def load(self, name: str) -> None:
        """Load a single plugin and its dependencies."""
        self.load_many([name])

    def load_many(self, names: Optional[Iterable[str]] = None) -> None:
        """
        Load multiple plugins (default: all registered) in dependency
        order.
        """
        target = list(names) if names is not None else list(self._plugins)
        order = self._resolve_order(target)

        for n in order:
            if n in self._loaded:
                continue
            plugin = self._plugins[n]
            logger.info("Loading plugin %s v%s", plugin.name, plugin.version)
            try:
                plugin.on_load(self)
            except Exception:
                logger.exception("Failed to load plugin %s", n)
                # Roll back any plugins loaded as part of this call.
                self._rollback_since(n, order)
                raise
            self._loaded[n] = plugin
            self._load_order.append(n)

    def _rollback_since(self, failed: str, order: List[str]) -> None:
        """Unload plugins loaded earlier in this batch before the failure."""
        idx = order.index(failed)
        for n in reversed(order[:idx]):
            if n in self._loaded:
                try:
                    self._plugins[n].on_unload(self)
                except Exception:  # pragma: no cover
                    logger.exception("Error during rollback unload of %s", n)
                self._loaded.pop(n, None)
                if n in self._load_order:
                    self._load_order.remove(n)

    def unload(self, name: str) -> None:
        """Unload a plugin. Fails if other loaded plugins depend on it."""
        if name not in self._loaded:
            raise PluginNotFoundError(f"Plugin '{name}' is not loaded")

        dependents = [
            other for other, p in self._loaded.items()
            if name in p.dependencies
        ]
        if dependents:
            raise DependencyError(
                f"Cannot unload '{name}'; required by: {dependents}"
            )

        plugin = self._loaded.pop(name)
        self._load_order.remove(name)
        logger.info("Unloading plugin %s", name)
        plugin.on_unload(self)

    def unload_all(self) -> None:
        """Unload every plugin in reverse load order."""
        for name in reversed(list(self._load_order)):
            plugin = self._loaded.pop(name, None)
            if plugin is None:
                continue
            try:
                plugin.on_unload(self)
            except Exception:  # pragma: no cover
                logger.exception("Error unloading %s", name)
        self._load_order.clear()

    # ------------------------------------------------------------------
    # Events
    # ------------------------------------------------------------------
    def dispatch(self, event: str, *args: Any, **kwargs: Any) -> Dict[str, Any]:
        """
        Dispatch an event to all loaded plugins (in load order).

        Returns a mapping of plugin-name to its ``on_event`` return value.
        Exceptions in handlers are logged but do not stop dispatch.
        """
        results: Dict[str, Any] = {}
        for name in self._load_order:
            plugin = self._loaded[name]
            try:
                results[name] = plugin.on_event(event, *args, **kwargs)
            except Exception:
                logger.exception("Plugin %s failed handling event %r", name, event)
                results[name] = None
        return results

    # ------------------------------------------------------------------
    # Introspection
    # ------------------------------------------------------------------
    def get(self, name: str) -> Plugin:
        """Return a registered plugin by name."""
        if name not in self._plugins:
            raise PluginNotFoundError(name)
        return self._plugins[name]

    @property
    def plugins(self) -> Dict[str, Plugin]:
        """Return a copy of the registered plugin mapping."""
        return dict(self._plugins)

    @property
    def loaded(self) -> List[str]:
        """Return loaded plugin names in load order."""
        return list(self._load_order)

    def is_loaded(self, name: str) -> bool:
        return name in self._loaded

    def __contains__(self, name: str) -> bool:
        return name in self._plugins

    def __len__(self) -> int:
        return len(self._plugins)
